xv = (a E^(-I v) + ad E^(I v))/2;
{Table[FullSimplify[mom[m] - (rho E^(I p))^m Exp[-I K t m (m - 1)] Exp[rho^2 (Exp[-2 I m K t] - 1)], rho > 0 && Element[{p, K, t}, Reals]], {m, 1, 3}],
